<p class="tool-buttons"><a href="/operations/">Operations</a><a href="/community/">Transmissions</a><a href="/industry/?view=fulcrum">Fulcrum market</a><a href="/signals/">Radio &amp; live channel</a><?php if($navActive==='community'): ?><a href="/community/submit.php">Submit art or a comic</a><?php if($viewer): ?><a href="/community/submissions.php">Your submissions</a><?php endif; endif; ?></p>
