<?php foreach($types as $type): $entries=CommunityNetwork::published($ledger,[$type==='propaganda'?'art':$type]); if(in_array($type,['art','propaganda'],true))$entries=array_values(array_filter($entries,fn($e)=>($e['category']??'fan-art')===($type==='propaganda'?'propaganda':'fan-art'))); if(in_array($type,['fleet','supply'],true)){$entries=array_values(array_filter($entries,fn($e)=>$e['status']==='published' && ($e['when']==='' || $e['when']>=gmdate('Y-m-d\TH:i'))));usort($entries,fn($a,$b)=>strcmp($a['when']?:'9999',$b['when']?:'9999'));} ?>
<section id="<?= escape($type) ?>" class="tool-section"><h2><?= escape($labels[$type]) ?></h2>
<?php if(!$entries): ?><div class="tool-card"><p><?= escape($help[$type]) ?></p><?php if($type==='fleet'): ?><a href="/war/guristas/">Open the War Room</a><?php elseif(in_array($type,['art','propaganda','comic'],true)): ?><a href="/community/submit.php">Send your work for review</a><?php endif; ?></div><?php endif; ?>
