<?php if($image): ?><a href="<?= escape(community_entry_url($entry)) ?>"><img class="community-thumbnail" loading="lazy" src="/community/media.php?id=<?= escape($image['id']) ?>" alt="<?= escape($entry['title']) ?>" width="<?= (int)$image['width'] ?>" height="<?= (int)$image['height'] ?>"></a><?php endif; ?>
<h3><?= escape($entry['title']) ?></h3><p><?= escape(preg_match('/^.{0,240}/us',$entry['body'],$match)?$match[0]:$entry['body']) ?><?= strlen($entry['body'])>strlen($match[0]??$entry['body'])?'…':'' ?></p>
<?php if($entry['credit']): ?><p>By <?= escape($entry['credit']) ?></p><?php endif; ?>
<?php if($entry['when']): ?><p><?= $type==='fleet'?'Departure':'Deadline' ?>: <?= escape(str_replace('T',' ',$entry['when'])) ?> UTC</p><?php endif; ?>
<?php if($entry['location']): ?><p><?= escape($entry['location']) ?></p><?php endif; ?>
<?php if($type==='supply'): $progress=CommunityNetwork::progress($ledger,$entry['id']); if($progress['target']): ?><p><?= number_format($progress['verified']) ?> / <?= number_format($progress['target']) ?> units verified · <?= number_format($progress['available']) ?> available to reserve</p><?php else: ?><p>Confirm quantity and reward with the organizer.</p><?php endif; endif; ?>
<a class="secondary-button community-card-action" href="<?= escape(community_entry_url($entry)) ?>"><?= escape(match($type){'comic'=>'Read episode','art','propaganda'=>'View artwork','report'=>'Read field report','supply'=>'Read order & reserve',default=>'Read full details'}) ?></a>
</article><?php endforeach; ?></div></section><?php endforeach; ?>
<?php if($navActive==='operations'): ?>
<section id="contributions" class="tool-section"><h2>Verified supply progress</h2><p>Only officer-approved deliveries count here. Reservations and unreviewed evidence are separate. Item quantities are tracked per order, not combined across unrelated items.</p>
<?php $jobs=CommunityNetwork::published($ledger,['supply']); if(!$jobs): ?><p>No public supply targets yet.</p><?php endif; ?>
<div class="tool-grid"><?php foreach($jobs as $job): $progress=CommunityNetwork::progress($ledger,$job['id']); ?><article class="tool-card"><h3><?= escape($job['title']) ?></h3><?php if($progress['target']): ?><p><?= number_format($progress['verified']) ?> / <?= number_format($progress['target']) ?> units of <?= escape($job['item']) ?> verified</p><progress max="<?= $progress['target'] ?>" value="<?= min($progress['target'],$progress['verified']) ?>" aria-label="<?= escape('Verified progress for '.$job['title']) ?>"></progress><?php endif; ?><p><?= $progress['deliveries'] ?> verified delivery records<?= $job['status']==='archived'?' · closed order':'' ?></p><a href="/operations/entry.php?id=<?= escape($job['id']) ?>">Order details</a></article><?php endforeach; ?></div></section>
<?php if($viewer): ?><section id="record" class="tool-section"><h2>Your supply record</h2><p>Evidence and review notes are private to you and staff. Approval does not make an automatic reward payment.</p><?php $mine=array_filter($ledger['claims'],fn($c)=>$c['actor']===(int)$viewer['character_id']); if(!$mine): ?><p>No reservations or deliveries recorded yet.</p><?php endif; ?><?php foreach(array_reverse($mine) as $claim): require __DIR__.'/supply-record.php'; endforeach; ?></section><?php endif; endif; ?>
